# PTX source for a simple batched fp16 GEMM (naïve implementation)
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry batched_gemm_fp16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 batch,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // -------------------------------------------------------------------------
    // Thread/block indices
    // -------------------------------------------------------------------------
    .reg .u32  %tid_x, %tid_y, %tid_z;
    .reg .u32  %bid_x, %bid_y, %bid_z;
    .reg .u32  %row, %col, %b;

    mov.u32 %tid_x, %tid.x;          // threadIdx.x  (0..15)
    mov.u32 %tid_y, %tid.y;          // threadIdx.y  (0..15)
    mov.u32 %tid_z, %tid.z;          // threadIdx.z  (always 0)

    mov.u32 %bid_x, %ctaid.x;        // blockIdx.x
    mov.u32 %bid_y, %ctaid.y;        // blockIdx.y
    mov.u32 %bid_z, %ctaid.z;        // blockIdx.z (batch index)

    // Global coordinates of the element this thread will compute
    mul.lo.u32 %row, %bid_y, 16;     // blockDim.y * blockIdx.y
    add.u32 %row, %row, %tid_y;      // + threadIdx.y

    mul.lo.u32 %col, %bid_x, 16;     // blockDim.x * blockIdx.x
    add.u32 %col, %col, %tid_x;      // + threadIdx.x

    mov.u32 %b, %bid_z;              // batch index

    // -------------------------------------------------------------------------
    // Load scalar parameters
    // -------------------------------------------------------------------------
    .reg .u64  %A, %B, %C;
    .reg .u32  %M, %N, %K, %batch;

    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];
    ld.param.u32 %batch, [batch];
    ld.param.u32 %M, [M];
    ld.param.u32 %N, [N];
    ld.param.u32 %K, [K];

    // Bounds check – if the thread falls outside the output matrix, exit.
    setp.ge.u32 %p1, %row, %M;
    setp.ge.u32 %p2, %col, %N;
    @%p1 bra DONE;
    @%p2 bra DONE;

    // -------------------------------------------------------------------------
    // Accumulator (use fp32 for better precision)
    // -------------------------------------------------------------------------
    .reg .f32  %sum;
    mov.f32 %sum, 0f00000000;        // zero

    // -------------------------------------------------------------------------
    // Loop over K dimension
    // -------------------------------------------------------------------------
    .reg .u32  %k;
    mov.u32 %k, 0;

LOOP_K:
    setp.ge.u32 %p_done, %k, %K;
    @%p_done bra END_LOOP_K;

    // ---- Load A[batch, row, k] (fp16) ------------------------------------
    // address = ((batch * M + row) * K + k) * 2
    .reg .u64 %addrA, %tmp64;
    .reg .u32 %tmp32;

    mul.lo.u32 %tmp32, %batch, %M;          // batch * M
    add.u32 %tmp32, %tmp32, %row;           // batch*M + row
    mul.lo.u64 %tmp64, %tmp32, %K;          // (batch*M+row) * K
    add.u32 %tmp32, %k, 0;                  // k
    mul.lo.u64 %addrA, %tmp64, 2;           // *sizeof(fp16)
    add.u64 %addrA, %A, %addrA;             // base + offset

    .reg .f16 %a_fp16;
    ld.global.f16 %a_fp16, [%addrA];

    // ---- Load B[batch, k, col] (fp16) ------------------------------------
    // address = ((batch * K + k) * N + col) * 2
    .reg .u64 %addrB;
    mul.lo.u32 %tmp32, %batch, %K;          // batch * K
    add.u32 %tmp32, %tmp32, %k;             // batch*K + k
    mul.lo.u64 %tmp64, %tmp32, %N;          // (batch*K+k) * N
    add.u32 %tmp32, %col, 0;                // col
    mul.lo.u64 %addrB, %tmp64, 2;           // *sizeof(fp16)
    add.u64 %addrB, %B, %addrB;             // base + offset

    .reg .f16 %b_fp16;
    ld.global.f16 %b_fp16, [%addrB];

    // ---- Convert to fp32, multiply, accumulate ---------------------------
    .reg .f32 %a_fp32, %b_fp32;
    cvt.rn.f32.f16 %a_fp32, %a_fp16;
    cvt.rn.f32.f16 %b_fp32, %b_fp16;
    mad.f32 %sum, %a_fp32, %b_fp32, %sum;

    // ---- Increment k ------------------------------------------------------
    add.u32 %k, %k, 1;
    bra LOOP_K;

END_LOOP_K:
    // -------------------------------------------------------------------------
    // Write result C[batch, row, col] as fp16 (rounded)
    // -------------------------------------------------------------------------
    .reg .f16 %c_fp16;
    cvt.rn.f16.f32 %c_fp16, %sum;

    // address = ((batch * M + row) * N + col) * 2
    .reg .u64 %addrC;
    mul.lo.u32 %tmp32, %batch, %M;          // batch * M
    add.u32 %tmp32, %tmp32, %row;           // batch*M + row
    mul.lo.u64 %tmp64, %tmp32, %N;          // *N
    add.u32 %tmp32, %col, 0;                // col
    mul.lo.u64 %addrC, %tmp64, 2;           // *sizeof(fp16)
    add.u64 %addrC, %C, %addrC;             // base + offset

    st.global.f16 [%addrC], %c_fp16;

DONE:
    ret;
}
