# -------------------------------------------------------------------------
# Python wrapper that loads the PTX and launches the kernel.
# -------------------------------------------------------------------------
import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # ptx_load is provided by the harness environment
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Batched matrix multiplication using the custom PTX kernel.
        All tensors must be on CUDA and have dtype torch.float16.
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        batch, M, K = A.shape
        b2, K2, N = B.shape
        assert batch == b2 and K == K2

        # Allocate output
        C = torch.empty(batch, M, N, dtype=torch.float16, device='cuda')

        # Grid: one block per 16×16 tile of the output matrix per batch
        grid_x = (N + 15) // 16
        grid_y = (M + 15) // 16
        grid_z = batch
        grid = (grid_x, grid_y, grid_z)

        # Block: 16×16 threads (256 threads total)
        block = (16, 16, 1)

        # Prepare argument list (raw pointers + integer sizes)
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            batch,
            M,
            N,
            K
        ]

        # Launch the kernel (ptx_launch provided by the harness)
        ptx_launch(self.module, "batched_gemm_fp16", grid, block, args)

        return C
